// Royalty-free background music generated by code, so every video can have its own track.
// Uso: node scripts/musica.mjs <estilo> <seed> <segundos> <salida.wav>
// Estilos: uke | ambient | lofi | tropical | cinematic
import { writeFileSync, mkdirSync } from 'node:fs';

const [estilo = 'uke', semilla = '1', seg = '90', out = `musica/${estilo}-${semilla}.wav`] = process.argv.slice(2);
const SR = 44100, DUR = Number(seg), N = Math.ceil(DUR * SR);
const L = new Float32Array(N), R = new Float32Array(N);
let seed = Number(semilla) * 7919 + 13; const rnd = () => ((seed = (seed * 16807) % 2147483647) / 2147483647);
const pick = (a) => a[Math.floor(rnd() * a.length)];
const hz = (m) => 440 * 2 ** ((m - 69) / 12);
const put = (i, v, pan = 0.5) => { if (i >= 0 && i < N) { L[i] += v * (1 - pan) * 2 * 0.5; R[i] += v * pan * 2 * 0.5; } };

// --- instruments ---
function pluck(t0, midi, vol, pan = 0.5, brillo = 0.5) {
  const p = Math.max(2, Math.round(SR / hz(midi))), buf = Float32Array.from({ length: p }, () => rnd() * 2 - 1);
  const s0 = Math.floor(t0 * SR), len = Math.min(SR * 2, N - s0), k1 = 0.5 - brillo * 0.0015;
  for (let i = 0, k = 0; i < len; i++, k = (k + 1) % p) { const s = buf[k]; buf[k] = k1 * (s + buf[(k + 1) % p]) * 0.999; put(s0 + i, s * vol, pan); }
}
function epiano(t0, midi, dur, vol, pan = 0.5) {
  const s0 = Math.floor(t0 * SR), len = Math.min(Math.floor((dur + 1) * SR), N - s0), f = hz(midi);
  for (let i = 0; i < len; i++) { const t = i / SR, env = Math.exp(-t * 1.8) * Math.min(1, t / 0.005);
    const v = (Math.sin(2 * Math.PI * f * t) + 0.25 * Math.sin(4 * Math.PI * f * t) * Math.exp(-t * 6)) * env * (1 + 0.15 * Math.sin(2 * Math.PI * 4 * t)) * vol; put(s0 + i, v, pan); }
}
function pad(t0, dur, midis, vol) {
  const s0 = Math.floor(t0 * SR), len = Math.min(Math.floor(dur * SR), N - s0); let lpL = 0, lpR = 0;
  const ph = midis.flatMap((m) => [[hz(m) * 0.997, rnd()], [hz(m) * 1.003, rnd()]]);
  for (let i = 0; i < len; i++) { const t = i / SR, env = Math.min(1, t / 1.5, (dur - t) / 1.5);
    let a = 0, b = 0; ph.forEach(([f, o], j) => { const s = ((f * t + o) % 1) * 2 - 1; if (j % 2) a += s; else b += s; });
    lpL += (a - lpL) * 0.03; lpR += (b - lpR) * 0.03; L[s0 + i] += lpL * env * vol / midis.length; R[s0 + i] += lpR * env * vol / midis.length; }
}
function bell(t0, midi, vol, pan = 0.5) {
  const s0 = Math.floor(t0 * SR), len = Math.min(SR * 3, N - s0), f = hz(midi);
  for (let i = 0; i < len; i++) { const t = i / SR; put(s0 + i, Math.sin(2 * Math.PI * f * t + 1.5 * Math.exp(-t * 3) * Math.sin(2 * Math.PI * f * 3.5 * t)) * Math.exp(-t * 1.6) * vol, pan); }
}
function marimba(t0, midi, vol, pan = 0.5) {
  const s0 = Math.floor(t0 * SR), len = Math.min(SR / 2, N - s0), f = hz(midi);
  for (let i = 0; i < len; i++) { const t = i / SR; put(s0 + i, (Math.sin(2 * Math.PI * f * t) + 0.3 * Math.sin(2 * Math.PI * f * 4 * t) * Math.exp(-t * 30)) * Math.exp(-t * 9) * vol, pan); }
}
function bass(t0, midi, dur, vol) {
  const s0 = Math.floor(t0 * SR), len = Math.min(Math.floor(dur * SR), N - s0), f = hz(midi);
  for (let i = 0; i < len; i++) { const t = i / SR, env = Math.min(1, t / 0.01) * Math.min(1, (dur - t) / 0.05);
    put(s0 + i, (Math.sin(2 * Math.PI * f * t) + 0.2 * Math.sin(4 * Math.PI * f * t)) * env * vol); }
}
function kick(t0, vol) { const s0 = Math.floor(t0 * SR); for (let i = 0; i < SR / 3; i++) { const t = i / SR; put(s0 + i, Math.sin(2 * Math.PI * (45 + 90 * Math.exp(-t * 30)) * t) * Math.exp(-t * 9) * vol); } }
function snare(t0, vol) { const s0 = Math.floor(t0 * SR); let hp = 0, prev = 0; for (let i = 0; i < SR / 5; i++) { const t = i / SR, n = rnd() * 2 - 1; hp = 0.7 * (hp + n - prev); prev = n; put(s0 + i, (hp * 0.8 + Math.sin(2 * Math.PI * 190 * t) * 0.3) * Math.exp(-t * 22) * vol, 0.45); } }
function hat(t0, vol) { const s0 = Math.floor(t0 * SR); let hp = 0, prev = 0; for (let i = 0; i < SR / 25; i++) { const t = i / SR, n = rnd() * 2 - 1; hp = 0.5 * (hp + n - prev); prev = n; put(s0 + i, hp * Math.exp(-t * 120) * vol, 0.6); } }
function shaker(t0, vol) { const s0 = Math.floor(t0 * SR); for (let i = 0; i < SR / 15; i++) { const t = i / SR; put(s0 + i, (rnd() * 2 - 1) * Math.sin(Math.PI * t * 15) * vol, 0.65); } }

// --- harmony ---
const MAYOR = [0, 2, 4, 5, 7, 9, 11];
const PROGS = [[0, 4, 5, 3], [5, 3, 0, 4], [0, 2, 3, 3], [1, 4, 0, 5], [0, 5, 3, 4], [3, 0, 4, 5]];
const tonica = 55 + Math.floor(rnd() * 8); // G3..D4
const prog = pick(PROGS);
const acorde = (g, oct = 0) => [0, 2, 4].map((k) => tonica + oct + MAYOR[(g + k) % 7] + 12 * Math.floor((g + k) / 7));
const penta = [0, 2, 4, 7, 9].map((x) => tonica + 12 + x);

const tempo = { uke: 100, ambient: 60, lofi: 80, tropical: 104, cinematic: 72 }[estilo] + Math.floor(rnd() * 8);
const beat = 60 / tempo, compas = beat * 4;
for (let bar = 0, t = 0.2; t < DUR - 2; bar++, t += compas) {
  const g = prog[bar % 4], ch = acorde(g), raiz = tonica + MAYOR[g] - 24, fin = t > DUR - compas * 2;
  if (estilo === 'uke') {
    const patron = [0, 1, 1.5, 2.5, 3, 3.5];
    patron.forEach((p, j) => ch.concat(ch[0] + 12).forEach((m, k) => pluck(t + p * beat + k * 0.012 * (j % 2 ? -1 : 1), m, j % 2 ? 0.07 : 0.1, 0.35 + k * 0.1)));
    bass(t, raiz, beat * 1.8, 0.18); bass(t + beat * 2, raiz + 7, beat * 1.8, 0.14);
    for (let b = 0; b < 8; b++) shaker(t + b * beat / 2, b % 2 ? 0.03 : 0.05);
    if (bar % 2 === 1) penta.slice(0, 3).forEach((m, k) => pluck(t + beat * (2 + k * 0.5), pick(penta) + 12, 0.06, 0.7));
  } else if (estilo === 'ambient') {
    pad(t, compas + 1.5, ch.map((m) => m - 12).concat(ch[0]), 0.22);
    for (let k = 0; k < 3; k++) if (rnd() < 0.7) bell(t + rnd() * compas, pick(penta) + 12, 0.05, rnd());
    bass(t, raiz, compas, 0.07);
  } else if (estilo === 'lofi') {
    const sw = beat * 0.12;
    ch.concat(tonica + MAYOR[(g + 6) % 7] + 12 * Math.floor((g + 6) / 7)).forEach((m, k) => epiano(t + k * 0.02, m, compas, 0.08, 0.4 + k * 0.07));
    epiano(t + beat * 2.5 + sw, ch[1] + 12, beat, 0.05, 0.6);
    bass(t, raiz, beat * 1.5, 0.2); bass(t + beat * 2.5, raiz, beat, 0.15);
    if (!fin) { kick(t, 0.5); kick(t + beat * 2.5, 0.35); snare(t + beat, 0.22); snare(t + beat * 3, 0.22);
      for (let b = 0; b < 8; b++) hat(t + b * beat / 2 + (b % 2 ? sw : 0), b % 2 ? 0.05 : 0.08); }
  } else if (estilo === 'tropical') {
    for (let b = 0; b < 8; b++) marimba(t + b * beat / 2, ch[[0, 1, 2, 1, 0, 2, 1, 2][b]] + 12, 0.11, b % 2 ? 0.6 : 0.4);
    pad(t, compas + 0.5, ch, 0.08);
    bass(t, raiz, beat * 0.9, 0.2); bass(t + beat * 1.5, raiz, beat * 0.5, 0.15); bass(t + beat * 2, raiz + 7, beat * 0.9, 0.17);
    if (!fin && bar > 0) { for (let b = 0; b < 4; b++) kick(t + b * beat, 0.3); for (let b = 0; b < 8; b++) shaker(t + b * beat / 2, 0.035); snare(t + beat * 3.5, 0.08); }
  } else {
    pad(t, compas + 1.5, ch.map((m) => m - 12).concat(ch[0] + 12), 0.25);
    for (let b = 0; b < 8; b++) pluck(t + b * beat / 2, raiz + 12 + (b % 2 ? 12 : 0), 0.07, 0.5, 0.2);
    if (bar % 2 === 0) kick(t, 0.35);
    if (bar % 4 === 3) bell(t + beat * 2, pick(penta) + 12, 0.06, 0.7);
  }
}

// --- simple stereo reverb (comb filters) ---
for (const [buf, ds] of [[L, [1557, 1617, 1491, 1422]], [R, [1277, 1356, 1188, 1116]]]) {
  const seco = Float32Array.from(buf);
  for (const d of ds) { const c = new Float32Array(N); for (let i = d; i < N; i++) c[i] = seco[i - d] + c[i - d] * 0.72; for (let i = 0; i < N; i++) buf[i] += c[i] * 0.045; }
}

// --- normalize, fade, write ---
let pk = 0; for (let i = 0; i < N; i++) pk = Math.max(pk, Math.abs(L[i]), Math.abs(R[i]));
const g0 = 0.8 / (pk || 1), fade = SR * 2, data = Buffer.alloc(N * 4);
for (let i = 0; i < N; i++) { const g = g0 * Math.min(1, i / (SR * 0.5), (N - i) / fade);
  data.writeInt16LE(Math.max(-1, Math.min(1, L[i] * g)) * 32767 | 0, i * 4); data.writeInt16LE(Math.max(-1, Math.min(1, R[i] * g)) * 32767 | 0, i * 4 + 2); }
const h = Buffer.alloc(44);
h.write('RIFF', 0); h.writeUInt32LE(36 + data.length, 4); h.write('WAVEfmt ', 8); h.writeUInt32LE(16, 16);
h.writeUInt16LE(1, 20); h.writeUInt16LE(2, 22); h.writeUInt32LE(SR, 24); h.writeUInt32LE(SR * 4, 28);
h.writeUInt16LE(4, 32); h.writeUInt16LE(16, 34); h.write('data', 36); h.writeUInt32LE(data.length, 40);
mkdirSync(out.replace(/\/[^/]+$/, '') || '.', { recursive: true });
writeFileSync(out, Buffer.concat([h, data]));
console.log('ok', out, `${tempo} bpm`);
